import json
import locale
import os
from pathlib import Path
import subprocess
import sys

evidence = Path(\"verificacion-semana5\")
env = dict(os.environ, PYTHONDONTWRITEBYTECODE=\"1\")
encoding = env.get(\"PYTHONIOENCODING\", locale.getpreferredencoding(False)).split(\":\")[0]
def decode(data, preferred):
    for candidate in dict.fromkeys((preferred, \"utf-8-sig\", \"cp1252\")):
        try:
            return data.decode(candidate), candidate
        except UnicodeDecodeError:
            pass

for name in (\"logs_correctos.txt\", \"logs_errores.txt\", \"logs_correctos2.log\", \"logs_errores2.log\"):
    run = subprocess.run([sys.executable, \"analizador.py\", name], capture_output=True, env=env)
    matches = {}
