        matches[phase] = {}
        for stream in (\"stdout\", \"stderr\"):
            current = getattr(run, stream)
            previous = (evidence / f\"{name}.{phase}.{stream}.txt\").read_bytes()
            previous_text, stored_encoding = decode(previous, \"utf-8-sig\")
            matches[phase][stream] = {
                \"exact_bytes\": current == previous,
                \"same_text\": decode(current, encoding)[0].splitlines() == previous_text.splitlines(),
                \"stored_encoding\": stored_encoding,
            }
    print(json.dumps({\"name\": name, \"exit_code\": run.returncode, \"encoding\": encoding, \"stderr\": decode(run.stderr, encoding)[0], \"stdout\": decode(run.stdout, encoding)[0], \"historical_comparisons\": matches}, ensure_ascii=True))
